import React, { useState } from 'react';
import { User, MapPin, Search, X, FileText, AlertOctagon, Calendar, CreditCard, ChevronRight, Fingerprint, Clock, ShieldCheck, Phone, HardDrive, Zap } from 'lucide-react';

const CitizensTab = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState(null);
  const [activeFilter, setActiveFilter] = useState('PROFILE');

  const citizens = [
    { id: 'CZ-8821', name: 'ARJUN MEHTA', area: 'GANDHI_NAGAR', zone: 'ZONE_A', status: 'ACTIVE', phone: '+91 98XXX XXXXX', joined: '12_JAN_2025' },
    { id: 'CZ-4412', name: 'SARA KHAN', area: 'SILICON_VALLEY', zone: 'ZONE_C', status: 'OVERDUE', phone: '+91 88XXX XXXXX', joined: '05_FEB_2024' },
    { id: 'CZ-9003', name: 'VIKRAM SINGH', area: 'OLD_TOWN', zone: 'ZONE_B', status: 'ACTIVE', phone: '+91 77XXX XXXXX', joined: '22_NOV_2024' },
  ];

  const citizenStats = {
    reports: [
      { id: 'REP-102', type: 'OVERFLOW', date: '20 MAR', status: 'RESOLVED' },
      { id: 'REP-099', type: 'MISSED_PCK', date: '15 MAR', status: 'PENDING' },
    ],
    penalties: [
      { id: 'PNL-44', reason: 'MIXED_WASTE', amount: '₹500', date: '10 MAR' },
      { id: 'PNL-12', reason: 'LATE_DISPOSAL', amount: '₹200', date: '02 MAR' },
    ],
    schedules: [
      { day: 'MONDAY', time: '08:00 AM', type: 'DRY_WASTE' },
      { day: 'WEDNESDAY', time: '11:30 AM', type: 'WET_WASTE' },
    ],
    subscription: { plan: 'PREMIUM_ULTRA', price: '₹1,200/mo', expiry: 'APR 2026' }
  };

  const closeModal = () => {
    setSelectedCitizen(null);
    setActiveFilter('PROFILE');
  };

  return (
    <div className="w-full h-full flex flex-col gap-6 font-black italic uppercase tracking-tighter select-none">

      {/* 📋 DIRECTORY HEADER (Lemon Yellow) */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-[#FFF24D] p-6 rounded-[32px] border-[5px] border-[#47510B] shadow-[8px_8px_0_0_#47510B]">
        <div className="flex items-center gap-4 text-[#47510B]">
          <Fingerprint size={44} strokeWidth={2.5} />
          <div>
            <h1 className="text-3xl leading-none">CITIZEN_REGISTRY</h1>
            <p className="text-[10px] opacity-60">DATABASE_SCAN_ACTIVE // v2.0</p>
          </div>
        </div>
        <div className="relative w-full md:w-96">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-[#47510B]/40" size={22} />
          <input 
            type="text" 
            placeholder="FIND_CITIZEN_ID..." 
            className="w-full bg-white border-[4px] border-[#47510B] rounded-2xl p-4 pl-12 outline-none shadow-[4px_4px_0_0_#47510B] focus:bg-[#FDFAD8] transition-all"
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* 📋 GRID LIST: pb-40 ensures the bottom pill is NEVER cut */}
      <div className="flex-grow overflow-y-auto pr-2 pb-40 custom-scrollbar grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {citizens.map(c => (
          <div 
            key={c.id} 
            onClick={() => setSelectedCitizen(c)} 
            className="bg-white border-[4px] border-[#47510B] p-6 rounded-[40px] shadow-[6px_6px_0_0_#47510B] hover:translate-x-1 hover:-translate-y-1 hover:shadow-[10px_10px_0_0_#CAD23C] transition-all cursor-pointer flex justify-between items-center group"
          >
            <div>
              <p className="text-[10px] text-[#FF5B03] mb-1 font-bold">{c.id}</p>
              <h3 className="text-2xl text-[#47510B] leading-none mb-2">{c.name}</h3>
              <div className="flex gap-2">
                <span className="text-[10px] bg-[#A1AED1] px-2 py-0.5 rounded italic">@{c.area}</span>
              </div>
            </div>
            <div className="bg-[#47510B] p-2 rounded-xl text-[#FFF24D] group-hover:scale-110 transition-transform">
              <ChevronRight size={24} strokeWidth={3} />
            </div>
          </div>
        ))}
      </div>

      {/* 🏗️ DOSSIER MODAL (Brutalists Vibe) */}
      {selectedCitizen && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 md:p-8">
          {/* High Contrast Backdrop */}
          <div className="absolute inset-0 bg-[#47510B]/90 backdrop-blur-md animate-in fade-in duration-300" onClick={closeModal} />

          {/* Modal Container: 85% Height, Max-5xl for "Just Right" Width */}
          <div className="relative w-full max-w-5xl h-[85vh] bg-[#FDFAD8] border-[8px] border-[#47510B] rounded-[60px] shadow-[25px_25px_0_0_#000] overflow-hidden flex flex-col animate-in zoom-in-95 duration-300">

            {/* HEADER: GRASSY GREEN + SUNGOLD */}
            <div className="bg-[#47510B] p-8 text-white flex justify-between items-center relative overflow-hidden shrink-0 border-b-[6px] border-[#CAD23C]">
                <div className="absolute top-0 right-0 p-4 opacity-5 rotate-12 -translate-y-10 translate-x-10"><HardDrive size={240}/></div>
                <div className="flex gap-6 items-center relative z-10">
                    <div className="w-20 h-20 bg-[#FFF24D] border-4 border-white rounded-[28px] flex items-center justify-center text-[#47510B] shadow-[6px_6px_0_0_#000]">
                        <User size={48} strokeWidth={3} />
                    </div>
                    <div>
                        <div className="flex items-center gap-3 mb-2">
                            <span className="bg-[#FF5B03] px-4 py-1 rounded-full text-[10px] tracking-widest border-2 border-white shadow-[3px_3px_0_0_#000]">LVL_98_VERIFIED</span>
                            <span className="text-[#CAD23C] text-xs">// REF_{selectedCitizen.id}</span>
                        </div>
                        <h2 className="text-4xl md:text-6xl leading-none">{selectedCitizen.name}</h2>
                    </div>
                </div>
                <button onClick={closeModal} className="relative z-10 bg-[#AB1717] border-4 border-white p-4 rounded-3xl hover:scale-110 transition-all shadow-[5px_5px_0_0_#000]"><X size={32} /></button>
            </div>

            {/* NAV BAR: BLUE LINEN / SEED GREEN */}
            <div className="bg-[#A1AED1] p-3 flex gap-3 overflow-x-auto no-scrollbar shrink-0 border-b-[6px] border-[#47510B]">
              {[
                { id: 'PROFILE', label: 'IDENTITY', icon: <Fingerprint size={18}/> },
                { id: 'REPORTS', label: 'INCIDENTS', icon: <FileText size={18}/> },
                { id: 'PENALTIES', label: 'INFRACTIONS', icon: <AlertOctagon size={18}/> },
                { id: 'SCHEDULES', label: 'WINDOWS', icon: <Clock size={18}/> },
                { id: 'SUBS', label: 'BILLING', icon: <CreditCard size={18}/> }
              ].map(f => (
                <button 
                  key={f.id}
                  onClick={() => setActiveFilter(f.id)}
                  className={`flex items-center gap-3 px-8 py-3 rounded-2xl text-[11px] font-black transition-all border-4 ${activeFilter === f.id ? 'bg-[#FFF24D] text-[#47510B] border-[#47510B] shadow-[4px_4px_0_0_#000]' : 'bg-white/40 text-[#47510B] border-transparent hover:border-[#47510B]'}`}
                >
                  {f.icon} {f.label}
                </button>
              ))}
            </div>

            {/* CONTENT AREA: FLUID BUT DENSE */}
            <div className="flex-grow p-10 overflow-y-auto custom-scrollbar-green">

              {/* PROFILE */}
              {activeFilter === 'PROFILE' && (
                <div className="grid grid-cols-1 md:grid-cols-12 gap-8 animate-in slide-in-from-bottom-8">
                  <div className="md:col-span-8 space-y-8">
                    <section>
                      <label className="text-[#AB1717] text-xs mb-3 block border-b-4 border-[#AB1717] w-fit">GEO_RESIDENCE_LOC</label>
                      <p className="text-4xl md:text-5xl leading-tight text-[#47510B] underline decoration-[#CAD23C] decoration-8 underline-offset-4">{selectedCitizen.area}</p>
                    </section>
                    <div className="grid grid-cols-2 gap-6">
                       <div className="bg-white p-6 rounded-[35px] border-4 border-[#47510B] shadow-[8px_8px_0_0_#47510B]">
                          <label className="text-[10px] opacity-40">COMM_LINE</label>
                          <p className="text-2xl mt-1 text-[#47510B]">{selectedCitizen.phone}</p>
                       </div>
                       <div className="bg-white p-6 rounded-[35px] border-4 border-[#47510B] shadow-[8px_8px_0_0_#CAD23C]">
                          <label className="text-[10px] opacity-40">JOINED_NETWORK</label>
                          <p className="text-2xl mt-1 text-[#47510B]">{selectedCitizen.joined}</p>
                       </div>
                    </div>
                  </div>
                  <div className="md:col-span-4 bg-[#CAD23C] border-[6px] border-[#47510B] rounded-[50px] p-8 text-[#47510B] flex flex-col items-center justify-center text-center shadow-[12px_12px_0_0_#47510B]">
                     <ShieldCheck size={72} className="mb-4" />
                     <h3 className="text-3xl leading-none">STATUS:<br/>VERIFIED</h3>
                     <p className="mt-4 text-[10px] font-bold bg-[#47510B] text-white px-4 py-1 rounded-full">{selectedCitizen.zone}</p>
                  </div>
                </div>
              )}

              {/* REPORTS */}
              {activeFilter === 'REPORTS' && (
                <div className="space-y-6 animate-in slide-in-from-right-8">
                  {citizenStats.reports.map(r => (
                    <div key={r.id} className="bg-white border-4 border-[#47510B] p-6 rounded-[30px] flex justify-between items-center shadow-[6px_6px_0_0_#47510B] hover:bg-[#FFF24D] transition-colors">
                      <div className="flex items-center gap-6">
                        <div className="w-12 h-12 bg-[#FF5B03] rounded-2xl flex items-center justify-center text-white border-2 border-[#47510B]"><Zap size={24}/></div>
                        <div>
                          <h4 className="text-3xl text-[#47510B]">{r.type}</h4>
                          <p className="text-xs opacity-40 font-bold">{r.id} // {r.date}</p>
                        </div>
                      </div>
                      <span className="text-xs font-black bg-[#47510B] text-white px-8 py-3 rounded-2xl shadow-[4px_4px_0_0_#000]">{r.status}</span>
                    </div>
                  ))}
                </div>
              )}

              {/* PENALTIES */}
              {activeFilter === 'PENALTIES' && (
                <div className="space-y-6 animate-in slide-in-from-right-8">
                  {citizenStats.penalties.map(p => (
                    <div key={p.id} className="bg-[#AB1717] border-4 border-black p-8 rounded-[40px] flex justify-between items-center shadow-[8px_8px_0_0_#47510B] text-white">
                      <div>
                        <h4 className="text-3xl italic">{p.reason}</h4>
                        <p className="text-xs opacity-60 mt-1 font-bold">{p.id} // {p.date}</p>
                      </div>
                      <p className="text-5xl font-black bg-white text-[#AB1717] px-6 py-2 rounded-2xl border-4 border-black">{p.amount}</p>
                    </div>
                  ))}
                </div>
              )}

              {/* SCHEDULES */}
              {activeFilter === 'SCHEDULES' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-in slide-in-from-right-8">
                  {citizenStats.schedules.map(s => (
                    <div key={s.day} className="bg-white border-[6px] border-[#47510B] p-8 rounded-[40px] text-center shadow-[10px_10px_0_0_#CAD23C]">
                      <Calendar size={48} className="mx-auto mb-4 text-[#FF5B03]" />
                      <p className="text-xl text-[#AB1717]">{s.day}</p>
                      <p className="text-5xl leading-none text-[#47510B] mt-2">{s.time}</p>
                      <p className="text-[10px] mt-6 bg-[#47510B] text-white py-2 rounded-xl inline-block px-8">{s.type}</p>
                    </div>
                  ))}
                </div>
              )}

              {/* SUBS */}
              {activeFilter === 'SUBS' && (
                <div className="bg-[#FFF24D] border-[6px] border-[#47510B] p-12 rounded-[60px] flex flex-col md:flex-row justify-between items-center shadow-[15px_15px_0_0_#47510B] animate-in slide-in-from-bottom-8">
                   <div className="text-center md:text-left">
                      <h3 className="text-7xl text-[#47510B] leading-none">{citizenStats.subscription.plan}</h3>
                      <p className="text-xl opacity-40 mt-4 font-bold italic underline decoration-4 underline-offset-8">EXPIRES: {citizenStats.subscription.expiry}</p>
                   </div>
                   <div className="text-center md:text-right mt-10 md:mt-0">
                      <p className="text-6xl text-[#AB1717] font-black">{citizenStats.subscription.price}</p>
                      <button className="mt-6 bg-[#47510B] text-white px-10 py-4 rounded-[20px] text-xs hover:bg-[#FF5B03] transition-all shadow-[6px_6px_0_0_#000] border-2 border-white">AUTO_RENEW_ON</button>
                   </div>
                </div>
              )}

            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CitizensTab;
